# Only the canonical product site receives extension palette updates; no website input is read.
(r/'src/extension/site-bridge.js').write_text('''(() => {
 if(location.origin!=='https://cevir.haking.tr')return;
 const allowed=['indigo','purple','emerald','amber'];
 function send(value){if(allowed.includes(value))window.postMessage({type:'CEVIRMENX_PALETTE',palette:value},location.origin);}
 chrome.storage.sync.get('eklentiTemasi').then(x=>send(x.eklentiTemasi || 'indigo'));
 chrome.storage.onChanged.addListener((changes,area)=>{if(area==='sync'&&changes.eklentiTemasi)send(changes.eklentiTemasi.newValue);});
})();''',encoding='utf-8')
p=r/'src/extension/manifest.json';m=json.loads(p.read_text(encoding='utf-8'));m['content_scripts']=[x for x in m['content_scripts'] if x.get('js')!=['site-bridge.js']]+[{'matches':['https://cevir.haking.tr/*'],'js':['site-bridge.js'],'run_at':'document_idle'}];p.write_text(json.dumps(m,ensure_ascii=False,indent=2),encoding='utf-8')
